__NUXT_JSONP__("/anticorrupcion/eventos/impulsa_ethos_un_programa_de_capacitacion_para_fortalecer_a_los_comites_de_participacion_ciudadana_en_los_estados", (function(a,b,c,d,e){return {data:[{post:{slug:"impulsa_ethos_un_programa_de_capacitacion_para_fortalecer_a_los_comites_de_participacion_ciudadana_en_los_estados",title:"Impulsa Ethos un programa de capacitación  para fortalecer a los Comités de Participación Ciudadana en los estados",date:"2023-07-11T21:43:26.005Z",img:"https:\u002F\u002Fucarecdn.com\u002F618685de-958f-47e1-a0cd-c88dbc9399bc\u002F","img-alt":"Fortaleciendo a los CPC",autor:"Ethos",category:"anticorrupcion",extracto:"Este programa surge de un diagnóstico realizado por Ethos para conocer los conocimientos y habilidades que deben tener los integrantes del CPC y poner un piso mínimo en todas las áreas de conocimiento para fortalecer su impacto en la lucha anticorrupción.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"Tras realizar un diagnóstico para conocer las principales necesidades de capacitación de los Comités de Participación Ciudadana (CPC) de los Sistemas Anticorrupción, la semana pasada dio inicio el programa de capacitación Fortaleciendo a los CPC, que impulsamos desde Ethos con el apoyo de Secretaría Ejecutiva del Sistema Nacional Anticorrupción (SESNA) Oficina de Naciones Unidas contra la Droga y el Delito (UNODC por sus siglas en inglés) y National Endowment for Democracy. "}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"El programa, precisó Dalia Toledo, directora de Finanzas Públicas y Anticorrupción en Ethos, busca fortalecer el trabajo de los Comités de Participación Ciudadana de los Sistemas Anticorrupción, al brindarles conocimientos, habilidades y herramientas que son necesarios para el cumplimiento de sus funciones. De esta manera, explicó, se pretende crear un piso mínimo en todas las áreas de conocimiento que les son necesarias para que sus propuestas y proyectos puedan tener mucho mayo impacto en la lucha anticorrupción."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“Muchas veces, los integrantes de los CPC son expertos en una determinada área del conocimiento, pero desconocen otras que también son necesarias para el cumplimiento de todas sus atribuciones. Por ejemplo, puede que sean abogados que no saben mucho de temas de comunicación o expertos en participación ciudadana y derechos humanos pero ignoran cómo monitorear el gasto público”, dijo. "}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Fortaleciendo a los CPC tiene una duración de 4 meses, se imparte de manera virtual y cuenta con ponentes de instituciones de primer nivel, indicó el investigador anticorrupción en Ethos Emiliano Montes de Oca. Además, consta de 3 módulos, de los cuales el primero se enfoca en temas transversales, como el entramado legal de los sistemas anticorrupción y la creación, implementación y monitoreo de las políticas públicas anticorrupción. "}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"El segundo módulo, expresó, tiene que ver con el desarrollo de habilidades blandas como la negociación y el liderazgo, mientras que el tercero, cuenta con 4 especialidades: comunicación, participación ciudadana, sistema de denuncias y monitoreo del gasto público."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"A lo largo del curso y con los conocimientos que adquieran en él, las personas que participan desarrollarán proyectos de política pública que implementarán en sus estados, señaló, y agregó que en este primer pilotaje, participan 25 integrantes de CPC de 25 estados de la república. “Esperamos que el próximo año el programa pueda llegar a más CPC e incluso a personas que se dedican a la lucha anticorrupción como periodistas, integrantes de organizaciones de la sociedad civil y de la academia”, comentó."}]}]},dir:"\u002Feventos",path:"\u002Feventos\u002Fimpulsa_ethos_un_programa_de_capacitacion_para_fortalecer_a_los_comites_de_participacion_ciudadana_en_los_estados",extension:".md",createdAt:e,updatedAt:e}}],fetch:{},mutations:[]}}("text","element","p","\n","2023-09-12T15:29:17.045Z")));